<h1><?= $property?'Edit Property':'Add Property' ?></h1><form class='form-card' method='POST' action='<?= $action ?>'><?= csrf_field() ?><label>Host</label><select name='host_id'><?php foreach($hosts as $h): ?><option value='<?= $h['host_id'] ?>' <?= ($property['host_id']??'')==$h['host_id']?'selected':'' ?>><?= e($h['company_name']) ?></option><?php endforeach; ?></select><label>Location</label><select name='location_id'><?php foreach($locations as $l): ?><option value='<?= $l['location_id'] ?>' <?= ($property['location_id']??'')==$l['location_id']?'selected':'' ?>><?= e($l['district']) ?></option><?php endforeach; ?></select><label>Title</label><input name='title' value='<?= e($property['title']??'') ?>' required><label>Type</label><input name='property_type' value='<?= e($property['property_type']??'') ?>' required><label>Address</label><input name='address' value='<?= e($property['address']??'') ?>'><label>Bedrooms</label><input type='number' name='bedrooms' value='<?= e($property['bedrooms']??1) ?>'><label>Bathrooms</label><input type='number' name='bathrooms' value='<?= e($property['bathrooms']??1) ?>'><label>Price</label><input type='number' name='price_per_month' value='<?= e($property['price_per_month']??'') ?>'><label>Status</label><select name='availability_status'><option>Available</option><option>Unavailable</option><option>Under Review</option></select><label>Image Path</label><input name='image_path' value='<?= e($property['image_path']??'assets/images/property1.svg') ?>'><label>Description</label><textarea name='description'><?= e($property['description']??'') ?></textarea><button class='btn'>Save</button></form>
